export const SEOUL_WEATHER_URL='https://api.open-meteo.com/v1/forecast?latitude=37.5665&longitude=126.9780&current=temperature_2m,weather_code,precipitation,rain,showers,snowfall,is_day,wind_speed_10m&timezone=Asia%2FSeoul&forecast_days=1';
export const WEATHER_CACHE='pogeun-seoul-weather-v1';
export const weatherKind=c=>{const code=Number(c?.weather_code),rain=Number(c?.rain||0)+Number(c?.showers||0),snow=Number(c?.snowfall||0);if(snow>0&&rain>0)return'sleet';if(snow>0||[71,73,75,77,85,86].includes(code))return'snow';if([95,96,97,99].includes(code))return'thunder';if(rain>0||[51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return'rain';if([45,48].includes(code))return'fog';if([2,3].includes(code))return'cloud';return[0,1].includes(code)?'clear':'unknown';};
export const WEATHER_LABELS={clear:'맑음',cloud:'구름',fog:'안개',rain:'비',snow:'눈',sleet:'진눈깨비',thunder:'비·뇌우',unknown:'연결 대기'};
export const weatherHeadline=w=>'서울 · '+(w?.status==='offline'?'날씨 연결 실패':(Number.isFinite(w?.temperature)?Math.round(w.temperature)+'° · ':'')+(WEATHER_LABELS[w?.kind]||WEATHER_LABELS.unknown));
export function parseWeather(data,now=Date.now()){const c=data?.current,stamp=typeof c?.time==='string'?Date.parse(c.time+'+09:00'):NaN;if(!c||!Number.isFinite(c.weather_code)||!Number.isFinite(c.temperature_2m)||!Number.isFinite(stamp)||now-stamp>2*3600000||stamp-now>30*60000)throw Error('Weather data unavailable or stale');return{kind:weatherKind(c),temperature:c.temperature_2m,day:c.is_day!==0,wind:Number(c.wind_speed_10m)||0,time:c.time,stamp,checkedAt:now,status:'live'};}
export function createWeather({world,button,onUpdate=()=>{},fetcher=fetch,storage,now=Date.now}){
 if(storage===undefined)try{storage=globalThis.localStorage;}catch{storage=null;}
 let state={kind:'unknown',day:true,temperature:null,time:null,status:'loading'},pending=false,lastAttempt=0,intensity=0,lastTick=0,seed=0,nightLevel=0,cloudLevel=0,fogLevel=0,effectKind='unknown';
 try{const cached=JSON.parse(storage?.getItem(WEATHER_CACHE));if(cached?.stamp&&now()-cached.stamp<2*3600000&&WEATHER_LABELS[cached.kind])state={...cached,status:'cached'};}catch{}
 function notify(){if(button){const icon={clear:state.day?'☀':'☾',cloud:'☁',rain:'☂',snow:'❄',sleet:'❄',fog:'☁',thunder:'☂',unknown:'↻'}[state.kind];button.textContent=icon;button.setAttribute('aria-label','서울 날씨: '+WEATHER_LABELS[state.kind]);}onUpdate(state);}
 async function refresh(force=false){if(pending||!force&&now()-lastAttempt<60000)return;pending=true;lastAttempt=now();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetcher(SEOUL_WEATHER_URL,{signal:controller.signal,cache:'no-store'});if(!r.ok)throw Error('weather');state=parseWeather(await r.json(),now());try{storage?.setItem(WEATHER_CACHE,JSON.stringify(state));}catch{}}catch{if(state.stamp&&now()-state.stamp<2*3600000)state={...state,status:'cached'};else state={kind:'unknown',temperature:null,day:true,time:null,status:'offline'};}finally{clearTimeout(timer);pending=false;notify();}}
 function markup(){return '<foreignObject id="atmosphere" y="-600" width="960" height="2000" pointer-events="none"><canvas xmlns="http://www.w3.org/1999/xhtml" id="weather-canvas" width="960" height="2000" style="display:block;width:960px;height:2000px;pointer-events:none"></canvas></foreignObject>';}
 function tick(t,reduced=false){const dt=lastTick?Math.min(.05,(t-lastTick)/1000):0;lastTick=t;const canvas=world.querySelector('#weather-canvas');if(!canvas)return;const c=canvas.getContext('2d');c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,960,2000);c.setTransform(1,0,0,1,0,600);if(effectKind!==state.kind&&intensity<.03)effectKind=state.kind;const wet=effectKind===state.kind&&['rain','snow','sleet','thunder'].includes(state.kind)?1:0;intensity+=(wet-intensity)*Math.min(1,dt*.7);nightLevel+=((!state.day&&state.kind!=='unknown'?1:0)-nightLevel)*Math.min(1,dt*.5);cloudLevel+=((['cloud','rain','sleet','thunder','snow'].includes(state.kind)?state.kind==='cloud'?.08:.19:0)-cloudLevel)*Math.min(1,dt*.5);fogLevel+=((state.kind==='fog'?.26:0)-fogLevel)*Math.min(1,dt*.5);
 if(nightLevel>.001){c.fillStyle=`rgba(22,45,87,${nightLevel*.33})`;c.fillRect(0,-600,960,2000);}if(cloudLevel>.001){c.fillStyle=`rgba(75,100,130,${cloudLevel})`;c.fillRect(0,-600,960,2000);}if(fogLevel>.001){c.fillStyle=`rgba(235,240,238,${fogLevel})`;c.fillRect(0,-600,960,2000);}
 if(intensity<.01)return;const snow=effectKind==='snow'||effectKind==='sleet',n=reduced?16:snow?65:95,seconds=reduced?Math.floor(t/300)/3.3:t/1000;c.globalAlpha=intensity;
 for(let i=0;i<n;i++){const depth=.5+(i%7)/7,baseX=(i*137.31)%1000,baseY=(i*193.77)%2050;if(snow&&!(effectKind==='sleet'&&i%2)){const x=(baseX+Math.sin(seconds*.7+i)*14+seconds*(4+state.wind*.2))%990,y=(baseY+seconds*(14+25*depth))%2050-600;c.fillStyle=i%3?'#fffef1':'#d5e5ee';c.beginPath();c.arc(x,y,1.5+depth*1.6,0,Math.PI*2);c.fill();}else{const y=(baseY+seconds*(390+depth*180))%2050-600,x=(baseX+seconds*(10+state.wind*1.5))%990;c.strokeStyle='#d4e4ed';c.lineWidth=.8+depth;c.beginPath();c.moveTo(x,y);c.lineTo(x-3,y+9+depth*8);c.stroke();}}
 if(!snow)for(let i=0;i<9;i++){const phase=(seconds*.65+i*.17)%1;c.globalAlpha=(1-phase)*intensity*.25;c.strokeStyle='#e8eff0';c.lineWidth=1;c.beginPath();c.ellipse(270+i*49,375+(i%3)*29,2+phase*8,1+phase*3,0,0,Math.PI*2);c.stroke();}c.globalAlpha=1;
 }
 function description(){const offline=state.status==='offline';const when=state.time?state.time.slice(11,16)+' 기준':'';return{label:weatherHeadline(state),when,status:state.status==='live'?'서울 날씨 연동':state.status==='cached'?'최근 날씨 · 다시 연결 중':offline?'날씨 연결 실패':'날씨 연결 대기',detail:state.status==='live'?'서울 대표 지점의 날씨를 10분마다 확인해요.':state.status==='cached'?'연결을 다시 확인하고 있어요. 마지막으로 받은 날씨를 보여 드려요.':offline?'날씨를 받지 못했어요. 잠시 뒤 다시 확인하고, 연결되면 비와 눈이 자연스럽게 반영돼요.':'날씨를 아직 받지 못했어요. 연결되면 비와 눈이 자연스럽게 반영돼요.'};}
 const interval=setInterval(()=>refresh(),10*60000);const visible=()=>{if(!document.hidden)refresh();};document.addEventListener('visibilitychange',visible);notify();refresh(true);
 return{refresh,markup,tick,description,get state(){return state;},dispose(){clearInterval(interval);document.removeEventListener('visibilitychange',visible);}};
}
